  switch (action.type) {
    case CHANGE_BOARD_POSITION:
      ({ newArray, element, position } = getSlicedArray(
        [...state],
        action.draggedItem,
        action.dropedBoardId
      ));

      const dropedIndex = newArray.findIndex(
        item => item.id === action.dropedBoardId
      );

      return [
        ...newArray.slice(0, dropedIndex + position),
        element,
