            thumbnail_url:
              video.player_response.videoDetails.thumbnail.thumbnails[
                video.player_response.videoDetails.thumbnail.thumbnails.length -
                  1
              ].url,
            author: {
              name: video.author.name,
              avatarURL: video.author.avatar,
