{
  unsigned long currentMillis = millis();

  if (currentMillis - _previousMillis >= _interval)
  {
    _previousMillis = currentMillis;
    if (_ledState == LOW)
    {
      _ledState = HIGH;
    }
    else
    {
      _ledState = LOW;
    }

    // set the LED with the ledState of the variable:
    digitalWrite(_ledPin, _ledState);
  }
